WITH inner_cte1 AS ( SELECT fb.BUILDING_NAME, SUM(fr.AREA) AS total_room_area, fb.FCLT_BUILDING_KEY FROM FCLT_ROOMS fr JOIN FCLT_BUILDING fb ON fr.FCLT_BUILDING_KEY = fb.FCLT_BUILDING_KEY WHERE fr.MAJOR_USE_DESC IN ('RESIDENT', 'LABS') AND fb.BUILDING_TYPE = 'ACADEMIC' AND fb.OWNERSHIP_TYPE = 'OWNED' GROUP BY fb.BUILDING_NAME, fb.FCLT_BUILDING_KEY HAVING SUM(fr.AREA) > 1000 ), BuildingPeriods AS ( SELECT ic.BUILDING_NAME, fbh.FISCAL_PERIOD, ic.total_room_area, ic.FCLT_BUILDING_KEY FROM inner_cte1 ic JOIN FCLT_BUILDING_HIST fbh ON ic.FCLT_BUILDING_KEY = fbh.FCLT_BUILDING_KEY ), BuildingRoomArea AS ( SELECT bp.BUILDING_NAME, bp.FISCAL_PERIOD, bp.total_room_area, bp.FCLT_BUILDING_KEY FROM BuildingPeriods bp WHERE bp.total_room_area > 0 ), inner_cte2 AS ( SELECT fb.FCLT_BUILDING_KEY, fb.BUILDING_NAME, fbh.FISCAL_PERIOD, SUM(fbh.ASSIGNABLE_AREA) OVER ( PARTITION BY fb.CAMPUS_SECTOR ORDER BY fb.FCLT_BUILDING_KEY, fbh.FISCAL_PERIOD ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS running_assignable_area FROM FCLT_BUILDING fb JOIN FCLT_BUILDING_HIST fbh ON fb.FCLT_BUILDING_KEY = fbh.FCLT_BUILDING_KEY WHERE fb.BUILDING_TYPE = 'ACADEMIC' AND fb.SITE = 'MIT' AND fb.OWNERSHIP_TYPE = 'OWNED' AND fb.FCLT_BUILDING_KEY <> '32' ), BuildingAssignableArea AS ( SELECT icte.FCLT_BUILDING_KEY, icte.BUILDING_NAME, icte.FISCAL_PERIOD, icte.running_assignable_area, fb.EXT_GROSS_AREA FROM inner_cte2 icte JOIN FCLT_BUILDING fb ON icte.FCLT_BUILDING_KEY = fb.FCLT_BUILDING_KEY ) SELECT bra.BUILDING_NAME, bra.FISCAL_PERIOD, bra.total_room_area, baa.running_assignable_area, baa.EXT_GROSS_AREA FROM BuildingRoomArea bra JOIN BuildingAssignableArea baa ON bra.FCLT_BUILDING_KEY = baa.FCLT_BUILDING_KEY AND bra.FISCAL_PERIOD = baa.FISCAL_PERIOD ORDER BY bra.FISCAL_PERIOD, bra.BUILDING_NAME;